package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.net.URI;import java.time.*;import java.util.Map;import org.junit.jupiter.api.Test;import config.ConfiguracionMercadoPago;import dao.*;import negocio.*;import pagos.*;
class CreacionOrdenPagoOnlineServiceTest {private ConfiguracionMercadoPago cfg(){return ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","x","MP_WEBHOOK_SECRET","y","MP_PUBLIC_BASE_URL","https://club.example"));}@Test void creaCheckoutYCompletaOrden(){OrdenPagoDAO dao=mock(OrdenPagoDAO.class);PagoService pagos=mock(PagoService.class);IntentoPagoService intentos=mock(IntentoPagoService.class);when(pagos.totalAcreditado(9)).thenReturn(BigDecimal.ZERO);when(dao.guardar(any())).thenAnswer(i->{OrdenPago o=i.getArgument(0);o.setId(4);return o;});when(dao.completarCheckout(eq(4L),eq(0L),eq("pref-1"),anyString())).thenReturn(true);IntentoPago intento=new IntentoPago();intento.setId(7);intento.setNumeroIntento(1);when(intentos.iniciar(4)).thenReturn(intento);PasarelaPagoOnline p=mock(PasarelaPagoOnline.class);when(p.disponible()).thenReturn(true);when(p.crearCheckout(any())).thenReturn(new CheckoutCreado("pref-1",URI.create("https://www.mercadopago.com/checkout"),LocalDateTime.now().plusMinutes(10),"ref"));var s=new CreacionOrdenPagoClienteService(dao,pagos,new OrdenPagoService(),Clock.systemUTC(),p,intentos,cfg());OrdenPago o=s.crearOnline(9,new BigDecimal("6250"),LocalDateTime.now().plusMinutes(10),"Seña");assertEquals(EstadoOrdenPago.ESPERANDO_PAGO,o.getEstado());assertEquals("pref-1",o.getPreferenciaExternaId());verify(intentos).exitoso(7,"pref-1");}@Test void fallaCerradoSinPasarela(){var s=new CreacionOrdenPagoClienteService(mock(OrdenPagoDAO.class),mock(PagoService.class),new OrdenPagoService(),Clock.systemUTC(),new PasarelaPagoNoDisponible("off"),mock(IntentoPagoService.class),null);assertThrows(IllegalStateException.class,()->s.crearOnline(9,new BigDecimal("6250"),LocalDateTime.now(),"Seña"));}}
